/**
 * Synthesises the landing page demo's spoken lines (src/components/landing/demoScript.ts) with Deepgram, the same
 * voices the interview room uses, into public/demo/<id>.mp3, and writes how long each clip is to
 * src/components/landing/demoAudio.generated.ts so the demo gives every line exactly the time it takes to say.
 *
 *   DEEPGRAM_API_KEY=... bun scripts/make-demo-audio.ts
 *
 * Run it after editing a line in demoScript.ts; the MP3s and the generated file are committed.
 */
import { execFileSync } from "node:child_process";
import { mkdirSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";

import { DEMO, DEMO_VOICES } from "../src/components/landing/demoScript";

const key = process.env.DEEPGRAM_API_KEY;
if (!key) throw new Error("Set DEEPGRAM_API_KEY to synthesise the demo audio.");

const root = path.join(import.meta.dir, "..");
const outDir = path.join(root, "public", "demo");
mkdirSync(outDir, { recursive: true });

const BIT_RATE = 48_000;

/** The clip's length in ms: from macOS's afinfo where available, otherwise from the constant bit rate. */
function durationMs(file: string, bytes: number): number {
    try {
        const info = execFileSync("afinfo", [file], { encoding: "utf8" });
        const seconds = Number(/estimated duration:\s*([\d.]+)/.exec(info)?.[1]);
        if (seconds > 0) return Math.round(seconds * 1000);
    } catch {
        // Not macOS: fall back to the arithmetic, which is exact for a constant-bit-rate MP3.
    }
    return Math.round((bytes * 8 * 1000) / BIT_RATE);
}

// Clips for lines that are gone (or no longer spoken) are removed, so nothing stale is published.
const spoken = new Set(DEMO.filter((step) => step.speaker).map((step) => `${step.id}.mp3`));
for (const file of readdirSync(outDir)) {
    if (file.endsWith(".mp3") && !spoken.has(file)) rmSync(path.join(outDir, file));
}

const durations: Record<string, number> = {};
for (const step of DEMO) {
    if (!step.speaker) continue;
    const voice = DEMO_VOICES[step.speaker];
    const response = await fetch(`https://api.deepgram.com/v1/speak?model=${voice}&encoding=mp3&bit_rate=${BIT_RATE}`, {
        method: "POST",
        headers: { Authorization: `Token ${key}`, "Content-Type": "application/json" },
        body: JSON.stringify({ text: step.text }),
    });
    if (!response.ok) throw new Error(`Deepgram answered ${response.status} for "${step.id}": ${await response.text()}`);
    const audio = Buffer.from(await response.arrayBuffer());
    const file = path.join(outDir, `${step.id}.mp3`);
    writeFileSync(file, audio);
    durations[step.id] = durationMs(file, audio.length);
    console.log(`wrote public/demo/${step.id}.mp3 (${(audio.length / 1024).toFixed(0)} KB, ${(durations[step.id]! / 1000).toFixed(1)} s)`);
}

writeFileSync(
    path.join(root, "src", "components", "landing", "demoAudio.generated.ts"),
    `// Generated by scripts/make-demo-audio.ts from demoScript.ts. Do not edit by hand.\n` +
        `/** How long each spoken line of the demo takes to say, in ms. */\n` +
        `export const DEMO_AUDIO_MS: Record<string, number> = ${JSON.stringify(durations, null, 4)};\n`,
);
console.log("wrote src/components/landing/demoAudio.generated.ts");
